SELECT r.id, r.schedule_id, r.status, r.conversation_kind, r.created_at, r.updated_at, r.error_message, r.lease_owner, r.lease_until, r.precondition_ran_at, r.precondition_passed, r.precondition_result, r.conversation_id, r.scheduled_for, r.started_at, r.completed_at FROM (SELECT t.* FROM  (SELECT c.* , 0 AS should_delete FROM schedule_run c)  t) r WHERE $criteria.CompositeIn("r", $WriterKeys)